import { spawnSync, spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const ROOT = '/data';
const repoUrl = (process.env.GIT_REPO_URL || '').trim();
const branch = (process.env.GIT_BRANCH || 'main').trim() || 'main';
const entryFile = (process.env.BOT_ENTRY_FILE || 'index.js').trim() || 'index.js';
const customCmd = (process.env.START_COMMAND || '').trim();

async function syncGitHubRepo() {
  if (!repoUrl) return;
  const parsed = new URL(repoUrl);
  if (parsed.protocol !== 'https:' || (parsed.hostname !== 'github.com' && parsed.hostname !== 'www.github.com')) {
    console.error('[MSM] Nur öffentliche GitHub-HTTPS-URLs werden unterstützt.');
    process.exit(1);
  }
  const parts = parsed.pathname.replace(/^\/|\.git$|\/$/g, '').split('/').filter(Boolean);
  if (parts.length < 2) {
    console.error('[MSM] Ungültige Repository-URL.');
    process.exit(1);
  }
  const markerPath = path.join(ROOT, '.msm_repo_state.json');
  const desired = repoUrl + '@' + branch;
  if (fs.existsSync(markerPath)) {
    try {
      const prev = JSON.parse(fs.readFileSync(markerPath, 'utf8'));
      if (prev.source === desired) return;
    } catch {
      // neu synchronisieren
    }
  }
  const archiveUrl = 'https://github.com/' + encodeURIComponent(parts[0]) + '/' + encodeURIComponent(parts[1]) + '/archive/refs/heads/' + encodeURIComponent(branch) + '.tar.gz';
  console.log('[MSM] Lade Repository ' + parts[0] + '/' + parts[1] + ' (' + branch + ') ...');
  const resp = await fetch(archiveUrl);
  if (!resp.ok) {
    console.error('[MSM] Download fehlgeschlagen: HTTP ' + String(resp.status));
    process.exit(1);
  }
  const tarPath = '/tmp/msm-bot-repo.tar.gz';
  fs.writeFileSync(tarPath, Buffer.from(await resp.arrayBuffer()));
  const res = spawnSync('tar', ['-xzf', tarPath, '-C', ROOT, '--strip-components=1'], { stdio: 'inherit' });
  fs.rmSync(tarPath, { force: true });
  if (res.status !== 0) process.exit(res.status || 1);
  fs.writeFileSync(markerPath, JSON.stringify({ source: desired }));
}

await syncGitHubRepo();

const pkgPath = path.join(ROOT, 'package.json');
if (fs.existsSync(pkgPath) && !fs.existsSync(path.join(ROOT, 'node_modules'))) {
  console.log('[MSM] Installiere npm-Abhängigkeiten ...');
  const inst = spawnSync('npm', ['install', '--omit=dev'], { cwd: ROOT, stdio: 'inherit' });
  if (inst.status !== 0) process.exit(inst.status || 1);
}

let cmd = null;
if (customCmd) {
  cmd = customCmd.split(/\s+/).filter(Boolean);
} else if (fs.existsSync(pkgPath)) {
  try {
    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
    if (pkg.scripts && pkg.scripts.start) {
      cmd = ['npm', 'start'];
    }
  } catch {
    // Fallback auf BOT_ENTRY_FILE
  }
}

if (!cmd) {
  const resolved = path.resolve(ROOT, entryFile);
  if (!resolved.startsWith(ROOT + path.sep) || !fs.existsSync(resolved)) {
    console.log('[MSM] Keine Bot-Dateien gefunden. Lade deinen Bot im Datei-Tab hoch oder hinterlege GIT_REPO_URL unter Start & Variablen.');
    process.exit(1);
  }
  cmd = ['node', resolved];
}

const child = spawn(cmd[0], cmd.slice(1), { cwd: ROOT, stdio: 'inherit' });
child.on('exit', (code) => process.exit(code == null ? 0 : code));
process.on('SIGTERM', () => child.kill('SIGTERM'));
process.on('SIGINT', () => child.kill('SIGINT'));
